// Export integrity + standalone boot test for HydraScript playable exports.
//
// Uses the REAL HydraPlayer.buildPlayableHtml from hydra/player-runtime.js,
// then:
//   A. asserts the generated HTML is self-contained (expr module inlined,
//      no external dependencies),
//   B. boots the VERBATIM generated <script> blocks in a stubbed-DOM vm and
//      asserts document.documentElement.dataset.hydraPlayer === 'ready',
//   C. starts the exported runtime directly, pumps real rAF frames, and
//      asserts a Math.floor(...) block action actually ran in the game loop.

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const HYDRA = path.join(__dirname, '..', 'hydra');

let failures = 0;
function check(name, cond, detail) {
  if (cond) { console.log(`ok - ${name}`); }
  else { failures++; console.log(`NOT OK - ${name}${detail ? ' :: ' + detail : ''}`); }
}

// ---------- stubbed browser environment ----------
function makeCtx() {
  return new Proxy({}, {
    get(t, p) {
      if (p === Symbol.toPrimitive) return () => 0;
      return () => undefined;
    },
    set() { return true; }
  });
}
function makeBrowserStubs() {
  const rafCallbacks = [];
  const warned = [];
  const canvasListeners = {};
  const canvas = {
    width: 300, height: 150, tabIndex: 0, style: {},
    getContext: () => makeCtx(),
    addEventListener(type, fn) { (canvasListeners[type] = canvasListeners[type] || []).push(fn); },
    getBoundingClientRect: () => ({ left: 0, top: 0, width: 800, height: 600 }),
    focus() {}
  };
  const hud = { textContent: '' };
  const documentElement = { dataset: {} };
  const document = {
    documentElement,
    body: { appendChild() {} },
    querySelector: () => canvas,
    getElementById: (id) => (id === 'hydra-hud' ? hud : canvas),
    addEventListener() {},
    createElement: () => ({ style: {}, textContent: '' })
  };
  const sandbox = {
    console: Object.assign(Object.create(console), {
      warn: (...a) => { warned.push(a.join(' ')); }
    }),
    document,
    canvas, // exposed for the test only
    hud, // exposed for the test only
    canvasListeners, // exposed for the test only
    warned, // exposed for the test only
    addEventListener() {},
    requestAnimationFrame: (cb) => { rafCallbacks.push(cb); return rafCallbacks.length; },
    setTimeout: () => 0,
    clearTimeout: () => {}
  };
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  vm.createContext(sandbox);
  return { sandbox, rafCallbacks, canvas, hud, canvasListeners, warned, documentElement };
}

// ---------- test project ----------
// gameStart -> setVariable(score = Math.floor(25.7))
// middle mouse just-pressed -> setVariable(midClicked = 1)
// collision(ball, wall) -> hit = 1
// onFloor(jumper, platform) -> grounded = 1
// overlapTouch(orbA, orbB) -> touched = 1   (3px gap, tolerance 4)
// unknown block type -> runtime diagnostic (no crash)
// always -> setVariable(warnVar = mysteryVar + 1) -> expression diagnostic
const project = {
  id: 'boot-test-1',
  name: 'Boot Test',
  eventsVersion: 1,
  globalGridData: {
    0: { type: 'gameStart', kind: 'condition' },
    1: { type: 'setVariable', kind: 'action', varName: 'score', operation: 'set', value: 'Math.floor(25.7)' },
    60: { type: 'mouseClick', kind: 'condition', button: 'middle', mouseCondition: 'mouseButtonJustPressed' },
    61: { type: 'setVariable', kind: 'action', varName: 'midClicked', operation: 'set', value: '1' },
    120: { type: 'collision', kind: 'condition', object1: 'ball', object2: 'wall' },
    121: { type: 'setVariable', kind: 'action', varName: 'hit', operation: 'set', value: '1' },
    180: { type: 'onFloor', kind: 'condition', targetObject: 'jumper', platformObject: 'platform' },
    181: { type: 'setVariable', kind: 'action', varName: 'grounded', operation: 'set', value: '1' },
    240: { type: 'overlapTouch', kind: 'condition', object1: 'orbA', object2: 'orbB' },
    241: { type: 'setVariable', kind: 'action', varName: 'touched', operation: 'set', value: '1' },
    300: { type: 'noSuchBlock', kind: 'condition' },
    360: { type: 'always', kind: 'condition' },
    361: { type: 'setVariable', kind: 'action', varName: 'warnVar', operation: 'set', value: 'mysteryVar + 1' }
  },
  scenes: [{
    id: 1,
    name: 'Scene 1',
    objects: [
      { id: 1, name: 'player', kind: 'sprite', posX: 10, posY: 20, width: 40, height: 40, color: '#ff0000' },
      { id: 2, name: 'ball', kind: 'sprite', posX: 100, posY: 100, width: 40, height: 40, color: '#00ff00' },
      { id: 3, name: 'wall', kind: 'sprite', posX: 120, posY: 120, width: 40, height: 40, color: '#0000ff' },
      { id: 4, name: 'jumper', kind: 'sprite', posX: 100, posY: 160, width: 40, height: 40, color: '#ffff00' },
      { id: 5, name: 'platform', kind: 'sprite', posX: 90, posY: 200, width: 100, height: 20, color: '#888888', static: true },
      { id: 6, name: 'orbA', kind: 'sprite', posX: 300, posY: 300, width: 40, height: 40, color: '#ff00ff' },
      { id: 7, name: 'orbB', kind: 'sprite', posX: 343, posY: 300, width: 40, height: 40, color: '#00ffff' }
    ],
    gridData: {},
    worldWidth: 800, worldHeight: 600,
    viewportWidth: 800, viewportHeight: 600,
    bgColor: '#ffffff'
  }],
  currentSceneId: 1,
  assets: {}
};

