const html = ed.sandbox.window.HydraPlayer.buildPlayableHtml(project);
check('export produced non-empty HTML', typeof html === 'string' && html.length > 10000, `length=${html && html.length}`);
check('export inlines the shared expr module', html.includes('window.HydraExpr=(function hydraExprFactory'));
check('export inlines the shared input module', html.includes('window.HydraInput=(function hydraInputFactory'));
check('export inlines the shared audio module', html.includes('window.HydraAudio=(function hydraAudioFactory'));
check('export inlines the shared animation module', html.includes('window.HydraAnim=(function hydraAnimFactory'));
check('export inlines the shared audio-buses module', html.includes('window.HydraAudioBuses=(function hydraAudioBusesFactory'));
check('export inlines the shared camera-effects module', html.includes('window.HydraCameraFx=(function hydraCameraFxFactory'));
check('export inlines the shared frame-order module', html.includes('window.HydraFrame=(function hydraFrameFactory'));
check('export inlines the shared scene-reset module', html.includes('window.HydraSceneReset=(function hydraSceneResetFactory'));
check('export inlines the shared dispatch module', html.includes('window.HydraDispatch=(function hydraDispatchFactory'));
check('export embeds the player runtime', html.includes('installHydraPlayer'));
check('export sets the ready marker on boot', html.includes('dataset.hydraPlayer = "ready"'));
check('export has no external script dependencies', !/<script[^>]+src\s*=/.test(html));
check('export has no http(s) resource references', !/src\s*=\s*"https?:/.test(html) && !/href\s*=\s*"https?:/.test(html));
check('export escapes < in project JSON', !html.includes('</script>') || true); // extraction below is the real check

const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map(m => m[1]);
check('export contains exactly 2 inline scripts (runtime + boot)', scripts.length === 2, `found ${scripts.length}`);

// ---------- Phase B: boot the verbatim scripts in a fresh stubbed DOM ----------
const boot = makeBrowserStubs();
let bootError = null;
try {
  vm.runInContext(scripts[0], boot.sandbox, { filename: 'export-runtime.js' });
  vm.runInContext(scripts[1], boot.sandbox, { filename: 'export-boot.js' });
} catch (e) { bootError = e; }
check('exported scripts run without throwing', bootError === null, bootError && bootError.stack);
check('exported game reports ready', boot.documentElement.dataset.hydraPlayer === 'ready',
  `dataset.hydraPlayer=${JSON.stringify(boot.documentElement.dataset.hydraPlayer)}`);

