const state = play.sandbox.window.HydraPlayer.start(project, { canvas: play.canvas });
check('start() returns state', !!state && Array.isArray(state.objects));
let t = 0;
function pumpFrames(n) {
  for (let frame = 0; frame < n; frame++) {
    t += 16.67;
    const cbs = play.rafCallbacks.splice(0, play.rafCallbacks.length);
    cbs.forEach(cb => cb(t));
  }
}
pumpFrames(3);
check('gameStart block fired in exported runtime', state.variables.score !== undefined,
  `variables=${JSON.stringify(state.variables)}`);
check('Math.floor evaluated in exported game loop (score === 25)', state.variables.score === 25,
  `score=${JSON.stringify(state.variables.score)}`);
check('expression warning was captured (mysteryVar)', !!state.lastExpressionWarning &&
  state.lastExpressionWarning.includes('mysteryVar'), state.lastExpressionWarning);
check('scene objects present in exported run', state.objects.length === 7,
  `found ${state.objects.length}`);

// collision / onFloor / overlapTouch unification: preview and export must agree
check('collision condition fired in exported runtime (hit === 1)', state.variables.hit === 1,
  `hit=${JSON.stringify(state.variables.hit)}`);
check('onFloor condition fired in exported runtime (grounded === 1)', state.variables.grounded === 1,
  `grounded=${JSON.stringify(state.variables.grounded)}`);
check('overlapTouch tolerance honored in exported runtime (touched === 1)', state.variables.touched === 1,
  `touched=${JSON.stringify(state.variables.touched)}`);

// diagnostics: unknown block types and bad expressions are reported, not silent
const diagMessages = state.diagnostics.map(d => d.message);
check('unknown block type reported as diagnostic',
  diagMessages.some(m => m.includes('Unknown block type "noSuchBlock"')),
  JSON.stringify(diagMessages));
check('bad expression reported as diagnostic (not silently applied)',
  diagMessages.some(m => m.includes('mysteryVar')),
  JSON.stringify(diagMessages));
check('bad-expression action did not apply a value', state.variables.warnVar === undefined,
  `warnVar=${JSON.stringify(state.variables.warnVar)}`);
check('diagnostics went to console.warn', play.warned.length > 0,
  `warned=${JSON.stringify(play.warned.slice(0, 2))}`);
check('HUD badge shows warning count', /⚠/.test(play.hud.textContent),
  JSON.stringify(play.hud.textContent));

// middle mouse button: dispatch a real mousedown with button:1 through the
// listeners the runtime registered, then pump one frame.
const mousedowns = play.canvasListeners.mousedown || [];
check('runtime registered a mousedown listener', mousedowns.length > 0);
mousedowns.forEach(fn => fn({ button: 1, clientX: 100, clientY: 100 }));
check('middle button recorded in mouseButtons', state.mouseButtons.has(1));
pumpFrames(1);
check('middle-click condition fired in exported runtime (midClicked === 1)', state.variables.midClicked === 1,
  `midClicked=${JSON.stringify(state.variables.midClicked)}`);

// ---------- Phase D: switchScene is deferred to end of frame ----------
// Scene 1 has 'hero' (posX 50); scene 2 has no 'hero'. The grid runs
// switchScene THEN reads hero.posX in the same frame. With the old immediate
// swap, the read would run against scene 2's objects and yield 0; with the
// deferred swap it correctly reads 50 from the still-active scene 1.
