  // 10x6 map of 32px tiles at (0, 200); solid row at map row 4 (world y 328..360).
  function tileFloorObject() {
    const tiles = new Array(60).fill(-1);
    for (let c = 0; c < 10; c++) tiles[4 * 10 + c] = 0;
    return {
      id: 10, name: 'ground', kind: 'tilemap', posX: 0, posY: 200, width: 320, height: 192,
      tileSize: 32, cols: 10, rows: 6, tiles, tilesetAssetId: null, tilesetCols: 8, solidTiles: [0],
      static: true, physicsEnabled: false
    };
  }

  function tileHero() {
    return {
      id: 1, name: 'hero', kind: 'sprite', posX: 100, posY: 0, width: 24, height: 24,
      color: '#ff0000', static: false, physicsEnabled: true,
      physics: { gravity: 1.5, friction: 1, bounciness: 0, maxSpeed: 25 }
    };
  }

