    const proj = {
      id: 'phys-test-1', name: 'Phys Test', eventsVersion: 1, assets: {},
      globalGridData: gridData,
      scenes: [{
        id: 1, name: 'Main', gridData: {}, objects,
        worldWidth: 800, worldHeight: 600, viewportWidth: 800, viewportHeight: 600, bgColor: '#000'
      }],
      currentSceneId: 1
    };
    const state = pv.sandbox.window.HydraPlayer.start(proj, { canvas: pv.canvas });
    let tt = 0;
    function pump(n) {
      for (let f = 0; f < n; f++) {
        tt += 16.67; fakeNow += 16.67;
        const cbs = pv.rafCallbacks.splice(0, pv.rafCallbacks.length);
        cbs.forEach(cb => cb(tt));
      }
    }
    return { pv, state, pump };
