// ---------- Phase U: sprite transforms — Flip Object + Set Scale in exports ----------
// Flip Object mirrors the drawing (flipH/flipV); Set Scale writes the visual
// scaleX/scaleY factors; Position Check can read scaleX/scaleY. Both are
// drawing-only — collision keeps using width/height — and objects without the
// new fields (old projects) boot and draw with zero diagnostics.
{
  function startFxSession(gridData, objects) {
    const fx = makeBrowserStubs();
    fx.sandbox.localStorage = {
      getItem: () => null, setItem() {}, removeItem() {},
      key: () => null, get length() { return 0; }
    };
    let fakeNow = 0;
    fx.sandbox.performance = { now: () => fakeNow };
    ['hydra-expr.js', 'hydra-input.js', 'hydra-audio.js', 'hydra-buses.js',
     'hydra-tiles.js', 'hydra-physics2d.js', 'hydra-anim.js', 'hydra-tween.js',
     'hydra-ui.js', 'hydra-save.js', 'hydra-pause.js', 'hydra-camerafx.js', 'hydra-sceneinit.js', 'hydra-frame.js', 'hydra-physicsstep.js', 'hydra-scenereset.js', 'hydra-draw.js', 'hydra-dispatch.js', 'hydra-conditions.js', 'hydra-execute.js', 'hydra-particles.js',
     'hydra-actions.js', 'hydra-flow.js', 'hydra-collections.js', 'hydra-math.js', 'hydra-pick.js', 'hydra-layerfx.js', 'hydra-gltf.js', 'hydra-3d.js', 'hydra-profile.js', 'hydra-scriptapi.js', 'hydra-statemachine.js', 'hydra-blendspace.js', 'hydra-light2d.js', 'hydra-joints.js', 'hydra-skeleton.js', 'hydra-localization.js', 'hydra-dialogue.js', 'hydra-inventory.js', 'hydra-quest.js', 'hydra-achievement.js', 'hydra-cutscene.js', 'hydra-highscore.js', 'hydra-timescale.js', 'hydra-transition.js', 'hydra-camerafeel.js', 'hydra-parallax.js', 'hydra-spatialaudio.js', 'hydra-pathfind.js', 'hydra-ai.js', 'hydra-joystick.js', 'hydra-health.js', 'hydra-damagefx.js', 'hydra-respawn.js', 'hydra-spawn.js', 'hydra-lives.js', 'hydra-movement.js', 'hydra-platform.js', 'hydra-combat.js', 'hydra-xp.js', 'hydra-growth.js', 'hydra-scaling.js', 'hydra-boss.js', 'hydra-tags.js', 'hydra-minimap.js', 'hydra-attach.js', 'hydra-variables.js', 'hydra-functions.js', 'hydra-loops.js', 'hydra-events.js', 'hydra-trace.js', 'player-runtime.js'
    ].forEach(m => vm.runInContext(fs.readFileSync(path.join(HYDRA, m), 'utf8'), fx.sandbox, { filename: m }));
    const proj = {
      id: 'fx-test-1', name: 'Fx Test', eventsVersion: 1, assets: {},
      globalGridData: gridData,
      scenes: [{
        id: 1, name: 'Main', gridData: {}, objects,
        worldWidth: 800, worldHeight: 600, viewportWidth: 800, viewportHeight: 600, bgColor: '#000'
      }],
      currentSceneId: 1
    };
    const state = fx.sandbox.window.HydraPlayer.start(proj, { canvas: fx.canvas });
    let tt = 0;
    function pump(n) {
      for (let f = 0; f < n; f++) {
        tt += 16.67; fakeNow += 16.67;
        fx.rafCallbacks.splice(0, fx.rafCallbacks.length).forEach(cb => cb(tt));
      }
    }
    return { fx, state, pump };
  }

  const fxHero = (extra) => Object.assign({
    id: 1, name: 'hero', kind: 'sprite', posX: 100, posY: 100, width: 40, height: 40,
    color: '#ff0000'
  }, extra);
  const heroOf = (s) => s.state.objects.find(o => o.name === 'hero');
  const fxGameStart = { 0: { type: 'gameStart', kind: 'condition' } };

  // 1. flipObject horizontal + setScale + positionCheck reading scaleX
  {
    const s = startFxSession(Object.assign({
      1: { type: 'flipObject', kind: 'action', targetObject: 'hero', direction: 'horizontal' },
      2: { type: 'setScale', kind: 'action', targetObject: 'hero', scaleX: '2', scaleY: '0.5' },
      3: { type: 'positionCheck', kind: 'condition', targetObject: 'hero', property: 'scaleX', operator: '>=', value: '1.9' },
      4: { type: 'setVariable', kind: 'action', varName: 'bigX', operation: 'set', value: '1' }
    }, fxGameStart), [fxHero()]);
    s.pump(4);
    const h = heroOf(s);
    check('exported flipObject horizontal sets flipH only', h.flipH === true && h.flipV !== true,
      `flipH=${h.flipH} flipV=${h.flipV}`);
    check('exported setScale writes scaleX/scaleY', h.scaleX === 2 && h.scaleY === 0.5,
      `scaleX=${h.scaleX} scaleY=${h.scaleY}`);
    check('exported positionCheck reads scaleX', s.state.variables.bigX === 1,
      `bigX=${s.state.variables.bigX}`);
    check('flip + scale session runs with zero warnings', s.fx.warned.length === 0,
      s.fx.warned.slice(0, 3).join(' | '));
  }

  // 2. flipObject vertical
  {
    const s = startFxSession(Object.assign({
      1: { type: 'flipObject', kind: 'action', targetObject: 'hero', direction: 'vertical' }
    }, fxGameStart), [fxHero()]);
    s.pump(2);
    const h = heroOf(s);
    check('exported flipObject vertical sets flipV only', h.flipH !== true && h.flipV === true,
      `flipH=${h.flipH} flipV=${h.flipV}`);
  }

  // 3. flipObject both, then off restores
  {
    const s = startFxSession(Object.assign({
      1: { type: 'flipObject', kind: 'action', targetObject: 'hero', direction: 'both' }
    }, fxGameStart), [fxHero()]);
    s.pump(2);
    const h = heroOf(s);
    check('exported flipObject both sets flipH + flipV', h.flipH === true && h.flipV === true,
      `flipH=${h.flipH} flipV=${h.flipV}`);
    const s2 = startFxSession(Object.assign({
      1: { type: 'flipObject', kind: 'action', targetObject: 'hero', direction: 'off' }
    }, fxGameStart), [fxHero({ flipH: true, flipV: true })]);
    s2.pump(2);
    const h2 = heroOf(s2);
    check('exported flipObject off clears flipH + flipV', h2.flipH === false && h2.flipV === false,
      `flipH=${h2.flipH} flipV=${h2.flipV}`);
  }

  // 4. corrupt direction leaves the object untouched (never throws)
  {
    const s = startFxSession(Object.assign({
      1: { type: 'flipObject', kind: 'action', targetObject: 'hero', direction: 'sideways' }
    }, fxGameStart), [fxHero()]);
    s.pump(2);
    const h = heroOf(s);
    check('exported flipObject with a bad direction changes nothing',
      h.flipH !== true && h.flipV !== true, `flipH=${h.flipH} flipV=${h.flipV}`);
    check('corrupt flip direction runs with zero warnings', s.fx.warned.length === 0,
      s.fx.warned.slice(0, 3).join(' | '));
  }

  // 5. object without the new fields (an old project) draws fine — the
  // flip/scale coercion treats missing scaleX/scaleY as 1, flipH/flipV as off.
  {
    const s = startFxSession(fxGameStart, [fxHero()]);
    s.pump(4);
    const h = heroOf(s);
    check('legacy object without flip/scale fields draws with zero warnings',
      s.fx.warned.length === 0 && h.scaleX === undefined && h.flipH === undefined,
      s.fx.warned.slice(0, 3).join(' | '));
  }
}

