    0: { type: 'gameStart', kind: 'condition' },
    1: { type: 'addItem', kind: 'action', item: 'Gold coin', count: 5 },
    2: { type: 'addItem', kind: 'action', item: 'Brass key', count: 1 },
    3: { type: 'addItem', kind: 'action', item: 'Potion', count: 99 },
    60: { type: 'hasItem', kind: 'condition', item: 'Gold coin', count: 5 },
    61: { type: 'setVariable', kind: 'action', varName: 'sawHas5', operation: 'set', value: '1' },
    120: { type: 'hasItem', kind: 'condition', item: 'Brass key', count: 2 },
    121: { type: 'setVariable', kind: 'action', varName: 'sawHasKey2', operation: 'set', value: '1' },
    180: { type: 'itemCount', kind: 'condition', item: 'Gold coin', operator: '>=', value: 5 },
    181: { type: 'setVariable', kind: 'action', varName: 'sawCount5', operation: 'set', value: '1' },
    240: { type: 'keyJustPressed', kind: 'condition', key: 'KeyR' },
    241: { type: 'readItemCount', kind: 'action', item: 'Gold coin', varName: 'coinCount' },
    300: { type: 'keyJustPressed', kind: 'condition', key: 'KeyX' },
    301: { type: 'removeItem', kind: 'action', item: 'Gold coin', count: 3 },
    360: { type: 'keyJustPressed', kind: 'condition', key: 'KeyC' },
    361: { type: 'clearInventory', kind: 'action' },
    420: { type: 'hasItem', kind: 'condition', item: 'Gold coin', count: 1, reversed: true },
