    120: { type: 'keyJustPressed', kind: 'condition', key: 'KeyC' },
    121: { type: 'setAiBehavior', kind: 'action', targetObject: 'enemy', behavior: 'patrol', targetName: '', speed: 200, range: 300, patrolA: 'pointA', patrolB: 'pointB' },
